import React, { useState } from "react";
import { Search } from "lucide-react";

interface Props {
  searchTerm: string;
  setSearchTerm: (v: string) => void;
  filterCondition: "all" | "new" | "used";
  setFilterCondition: (v: "all" | "new" | "used") => void;
}

const SearchAndFilter: React.FC<Props> = ({
  searchTerm,
  setSearchTerm,
  filterCondition,
  setFilterCondition,
}) => {
  const [isFocused, setIsFocused] = useState(false);

  return (
    <div className="mb-6 md:mb-10 flex flex-col md:flex-row gap-4 md:gap-6 justify-center items-center">
      {/* Search input */}
      <div className="relative w-full max-w-xs md:max-w-md group">
        <Search
          className={`absolute left-3.5 top-1/2 -translate-y-1/2 h-5 w-5 pointer-events-none transition-colors duration-300 ${
            isFocused ? "text-red-500" : "text-gray-400"
          }`}
        />
        <input
          type="text"
          placeholder="Buscar marca o modelo..."
          value={searchTerm}
          onChange={(e) => setSearchTerm(e.target.value)}
          onFocus={() => setIsFocused(true)}
          onBlur={() => setIsFocused(false)}
          className="pl-11 pr-4 py-3 w-full rounded-xl bg-white border border-gray-200 text-gray-800 placeholder-gray-400 focus:outline-none focus:border-red-500 focus:ring-2 focus:ring-red-500/20 shadow-sm transition-all duration-300 focus:shadow-md"
        />
      </div>

      {/* Segmented filter control */}
      <div className="inline-flex rounded-xl bg-white border border-gray-200 shadow-sm p-1 gap-0 w-full sm:w-auto">
        {(
          [
            { key: "all", label: "Todos" },
            { key: "new", label: "0 KM" },
            { key: "used", label: "Usados" },
          ] as const
        ).map(({ key, label }) => (
          <button
            key={key}
            onClick={() => setFilterCondition(key)}
            className={`relative flex-1 sm:flex-none px-4 sm:px-6 py-2.5 rounded-lg font-semibold text-sm transition-all duration-300 focus:outline-none focus-visible:ring-2 focus-visible:ring-red-400 focus-visible:ring-offset-1 ${
              filterCondition === key
                ? "bg-red-600 text-white shadow-md shadow-red-600/25"
                : "bg-transparent text-gray-500 hover:text-gray-800 hover:bg-gray-50"
            }`}
          >
            {label}
          </button>
        ))}
      </div>
    </div>
  );
};

export default SearchAndFilter;